import java.util.Scanner;

public class Main {
    static class UnionFindSet {
        int[] parent;
        int[] rank;

        void init(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; ++i) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void merge(int a, int b) {
            a = find(a);
            b = find(b);
            if (a != b) {
                if (rank[a] < rank[b]) {
                    int temp = a;
                    a = b;
                    b = temp;
                }
                parent[b] = a;
                if (rank[a] == rank[b]) {
                    rank[a]++;
                }
            }
        }
    }

    static long binPow(long base, int exp, long mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        final long MOD = 1000000007L;

        if (k == 0) {
            System.out.println(binPow(n, n - 1, MOD));
            sc.close();
            return;
        }

        UnionFindSet ufs = new UnionFindSet();
        ufs.init(n);
        for (int i = 0; i < n; ++i) {
            ufs.merge(i, (int)((long)i * k % n));
        }

        long result = 1;
        for (int i = 0; i < n; ++i) {
            if (ufs.find(i) != i) continue;
            long t = binPow(k, ufs.rank[ufs.find(i)], n);
            if (t == 1) {
                result = (result * n) % MOD;
            }
        }

        System.out.println(result);
        sc.close();
    }
}
